// Per-widget browser harness: renders each widget's fixtures through its REAL element and runs its test.js.
//
//   node tools/run-tests.mjs tests/widgets/index.html            # all widgets, dist/houseview.js
//   .../tests/widgets/index.html?kind=light,cover                # some widgets
//   ...?manifest=/tests/fixtures/mini-engine/manifest.js&widgets=/tests/fixtures/mini-engine/src/widgets
//                                                                  # another widget tree (the mini engine fixture)
//
// Inputs: tests/widgets/manifest.js (generated by tools/gen-widgets.mjs: [{type, load:  => import(test.js)}]),
// src/widgets/<type>/fixtures.js for the variants, and the bundle given by `?src=` (default /dist/houseview.js).
//
// What the harness guarantees to a test.js (docs/widget-api.md):
//   * a recording mock hass per mount (tests/fixtures/mock-hass.js), no network, no Home Assistant;
//   * a fixed clock (2026-10-15 10:10 Europe/London) and intervals that only fire through h.advance(ms);
//   * window.confirm that records its messages and answers h.confirmWith(true|false) (default: false);
//   * every mounted element removed after each widget's test (so disconnectedCallback runs).
//
// Per variant it also runs two automatic checks (mounts and renders; every enabled control can be pressed without
// an error), so a widget with no hand-written assertions still proves it renders and does not crash.

import {createMockHass} from '../fixtures/mock-hass.js';

export const FIXED_NOW = Date.UTC(2026, 9, 15, 9, 10, 0);

/** Install a fixed clock and fake setInterval. Must run before the bundle is imported. */
export function installDeterminism() {
  const RealDate = Date;
  let offset = 0;
  class FixedDate extends RealDate {
    constructor(...args) {
      if (args.length === 0) super(FIXED_NOW + offset);
      else super(...args);
    }
    static now() {
      return FIXED_NOW + offset;
    }
  }
  window.Date = FixedDate;

  // Intervals are fake: they only fire through h.advance(ms). Exception: the runner's own polling (puppeteer injects
  // its code under a pptr: source URL) must keep a real timer, or it would wait for the summary forever.
  const realSetInterval = window.setInterval.bind(window);
  const realClearInterval = window.clearInterval.bind(window);
  const intervals = new Map();
  let nextId = 1000000;
  window.setInterval = (fn, ms = 0, ...args) => {
    if (new Error().stack?.includes('pptr:')) return realSetInterval(fn, ms, ...args);
    intervals.set(++nextId, {fn: () => fn(...args), ms: Math.max(1, ms), due: ms});
    return nextId;
  };
  window.clearInterval = (id) => {
    if (!intervals.delete(id)) realClearInterval(id);
  };

  const confirms = [];
  let answer = false;
  window.confirm = (message) => {
    confirms.push(String(message));
    return answer;
  };

  return {
    confirms,
    confirmWith: (value) => {
      answer = !!value;
    },
    now: () => FIXED_NOW + offset,
    /** Move the fake clock forward and fire due intervals in order. */
    advance(ms) {
      const end = offset + ms;
      let guard = 0;
      for (;;) {
        let next = null;
        for (const entry of intervals.values())
          if (entry.due <= end && (!next || entry.due < next.due)) next = entry;
        if (!next || ++guard > 10000) break;
        offset = Math.max(offset, next.due);
        next.due += next.ms;
        try {
          next.fn();
        } catch (e) {
          console.error(`interval callback threw: ${e.message}`);
        }
      }
      offset = end;
    },
    intervalCount: () => intervals.size
  };
}

const delay = (ms) => new Promise((r) => setTimeout(r, ms));
const frame = () => new Promise((r) => requestAnimationFrame(() => r()));

/** Let microtasks, the hass-driven render and one layout pass finish. */
export async function settle(ms = 20) {
  await Promise.resolve();
  await frame();
  await delay(ms);
}

/** Resolve a manifest/fixtures module URL relative to this file's directory (tests/widgets). */
const fixturesUrl = (type, base = '../../src/widgets') =>
  new URL(`${base.replace(/\/$/, '')}/${type}/fixtures.js`, import.meta.url).href;

/**
 * Build the handle given to a widget's test.js for one widget type.
 * @param {{type: string, env: ReturnType<typeof installDeterminism>, stage: Element, check: Function}} opts
 */
export function createHandle({type, env, stage, check, variants}) {
  const mounted = [];

  /**
   * Mount a fixture variant through the widget's real element.
   * @param {{widget: Object, states: Object, config?: Object, hass?: Object}} variant
   * @param {{as?: 'standalone'|'card', size?: string, config?: Object, hass?: Object, width?: number, height?: number}} [opts]
   *   as 'standalone' (default): <houseview-TYPE-card>; as 'card': a carousel <houseview-card> with widgets:[widget]
   *   (needed for alias types such as `scene`, camera_gallery and multi-widget behaviour).
   */
  async function mount(variant, opts = {}) {
    const mock = createMockHass({
      ...(variant.hass || {}),
      ...(opts.hass || {}),
      states: variant.states
    });
    const widget = {...variant.widget, ...(opts.size ? {size: opts.size} : {})};
    const extra = {...(variant.config || {}), ...(opts.config || {})};
    const holder = document.createElement('section');
    holder.dataset.widgetType = type;
    holder.style.cssText = `width:${opts.width ?? 420}px;height:${opts.height ?? 320}px;position:relative;overflow:hidden`;
    stage.append(holder);

    let el;
    let card;
    // widgets with `standalone: false` have no element of their own: they are mounted in a carousel
    const mode = customElements.get(`houseview-${type}-card`) ? opts.as || 'standalone' : 'card';
    if (mode === 'card') {
      el = document.createElement('houseview-card');
      holder.append(el);
      el.setConfig({...extra, widgets: [{type, ...widget}]});
      card = el;
    } else {
      el = document.createElement(`houseview-${type}-card`);
      holder.append(el);
      const {type: aliasType, ...rest} = widget;
      void aliasType; // an alias type (scene...) only exists in carousel mode; the standalone element is the canonical kind
      el.setConfig({type: `custom:houseview-${type}-card`, ...rest, ...extra});
      // the standalone card embeds the controller (docs/architecture.md); `_inner` is the field holding it
      card = el._inner || el.shadowRoot?.querySelector('houseview-card');
    }
    const infos = [];
    el.addEventListener('hass-more-info', (e) => infos.push(e.detail?.entityId));
    el.hass = mock.hass;
    await settle();

    const root = () => card?.shadowRoot || el.shadowRoot;
    const t = {
      el,
      card,
      mock,
      hass: mock.hass,
      infos,
      get root() {
        return root();
      },
      get calls() {
        return mock.calls;
      },
      q: (selector) => root()?.querySelector(selector) ?? null,
      qa: (selector) => [...(root()?.querySelectorAll(selector) ?? [])],
      text: (selector) => root()?.querySelector(selector)?.textContent.trim() ?? null,
      /** Press the button carrying data-action (and, optionally, data-entity). Resets t.calls first. */
      async click(action, entity) {
        const selector = `button[data-action="${action}"]${entity ? `[data-entity="${entity}"]` : ''}`;
        const button = root()?.querySelector(selector);
        if (!button) throw new Error(`no ${selector} in the rendered widget`);
        mock.calls.length = 0;
        button.click();
        await settle();
        return button;
      },
      /** Call the controller's _act directly (bypasses disabled buttons, like a stale click would). */
      async act(action, id) {
        mock.calls.length = 0;
        await card._act(action, id);
        await settle();
      },
      /** Merge into an entity in place and hand hass back to the card (the way Home Assistant pushes updates). */
      async setState(id, patch) {
        mock.setState(id, patch);
        el.hass = mock.hass;
        await settle();
      },
      async settle(ms) {
        await settle(ms);
      },
      remove() {
        el.remove();
        holder.remove();
      }
    };
    mounted.push(t);
    return t;
  }

  return {
    type,
    mount,
    check,
    variants,
    wait: delay,
    settle,
    now: env.now,
    advance: env.advance,
    confirms: env.confirms,
    confirmWith: env.confirmWith,
    cleanup() {
      for (const t of mounted.splice(0)) {
        try {
          t.remove();
        } catch {
          /* already gone */
        }
      }
    }
  };
}

/** Minimal doubles for the Home Assistant elements the card uses (the real ones live in the HA frontend). */
export function defineDoubles() {
  const define = (tag, ctor) => customElements.get(tag) || customElements.define(tag, ctor);
  define('ha-icon', class extends HTMLElement {});
  define('ha-card', class extends HTMLElement {});
  define('ha-form', class extends HTMLElement {});
  define(
    'hui-stack-card-editor',
    class extends HTMLElement {
      setConfig(config) {
        this.config = config;
      }
    }
  );
}

/**
 * Run every widget in the manifest.
 * @param {{params: URLSearchParams, results: Element, summary: Element, stage: Element}} opts
 */
export async function runSuite({params, results, summary, stage}) {
  const src = params.get('src') || '/dist/houseview.js';
  const env = installDeterminismOnce();
  defineDoubles();
  let passed = 0;
  let failed = 0;
  const errors = [];
  // "ResizeObserver loop completed with undelivered notifications" is a benign layout notice, not a widget error.
  const record = (message) => {
    if (!/ResizeObserver loop/.test(message)) errors.push(message);
  };
  window.addEventListener('error', (e) => {
    record(e.message);
    if (/ResizeObserver loop/.test(e.message)) e.stopImmediatePropagation();
  });
  window.addEventListener('unhandledrejection', (e) =>
    record(String(e.reason?.message || e.reason))
  );
  const add = (ok, text) => {
    const li = document.createElement('li');
    li.textContent = `${ok ? 'PASS' : 'FAIL'} — ${text}`;
    results.append(li);
    ok ? passed++ : failed++;
  };
  const finish = (text) => {
    summary.textContent = `${passed} passed; ${failed} failed.${text ? ` ${text}` : ''}`;
    return {passed, failed};
  };

  let manifest;
  try {
    manifest = (await import(/* @vite-ignore */ params.get('manifest') || './manifest.js')).default;
  } catch (e) {
    add(false, `tests/widgets/manifest.js could not be loaded (run npm run gen): ${e.message}`);
    return finish();
  }
  const only = (params.get('kind') || '').split(',').filter(Boolean);
  const entries = manifest.filter((m) => !only.length || only.includes(m.type));
  if (!entries.length) {
    return finish(
      manifest.length
        ? `No widget matches ?kind=${only.join(',')}.`
        : 'No widgets registered yet (the manifest is empty).'
    );
  }

  try {
    await import(/* @vite-ignore */ src);
  } catch (e) {
    add(false, `bundle ${src} failed to load: ${e.message}`);
    return finish();
  }

  for (const entry of entries) {
    const check = (name, ok) => add(!!ok, `${entry.type}: ${name}`);
    const before = passed + failed;
    let handle;
    try {
      const variants = (await import(fixturesUrl(entry.type, params.get('widgets') || undefined)))
        .variants;
      if (!variants || !Object.keys(variants).length)
        throw new Error('fixtures.js exports no variants');
      handle = createHandle({type: entry.type, env, stage, check, variants});

      // automatic per-variant checks
      for (const [name, variant] of Object.entries(variants)) {
        errors.length = 0;
        try {
          const t = await handle.mount(variant, {as: 'standalone'});
          const rendered = !!t.q('[data-widget="0"]');
          const pressed = [];
          for (const button of t.qa('button[data-action]')) {
            if (button.disabled) continue;
            handle.confirmWith(true);
            button.click();
            pressed.push(button.dataset.action);
            await settle(10);
          }
          t.remove();
          check(`variant "${name}" mounts and renders its tile`, rendered);
          check(
            `variant "${name}": pressing every enabled control (${pressed.length}) raises no error`,
            errors.length === 0
          );
          if (errors.length) console.error(`${entry.type}/${name}: ${errors.join(' | ')}`);
        } catch (e) {
          check(`variant "${name}" mounts without throwing (${e.message})`, false);
        } finally {
          env.confirmWith(false);
          env.confirms.length = 0;
        }
      }

      // the widget's own test
      const test = (await entry.load()).default;
      if (typeof test !== 'function')
        throw new Error('test.js must default-export an async function');
      const own = passed + failed;
      await test(handle);
      if (passed + failed === own) check('test.js made no check() calls', false);
    } catch (e) {
      check(`test.js threw: ${e.message}`, false);
      console.error(e);
    } finally {
      handle?.cleanup();
      env.confirmWith(false);
      env.confirms.length = 0;
    }
    if (passed + failed === before) add(false, `${entry.type}: produced no checks`);
  }
  return finish();
}

let determinism;
function installDeterminismOnce() {
  return (determinism ||= installDeterminism());
}
